#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <linux/netlink.h>
#include <linux/genetlink.h>
#include <net/if.h>
#include <errno.h>

#define NETDEV_FAMILY_NAME "netdev"
#define NETDEV_CMD_QUEUE_GET 10

// Attributes for NETDEV_CMD_QUEUE_GET
#define NETDEV_A_QUEUE_ID 1
#define NETDEV_A_QUEUE_IFINDEX 2
#define NETDEV_A_QUEUE_TYPE 3

#define NETDEV_QUEUE_TYPE_RX 0
#define NETDEV_QUEUE_TYPE_TX 1

struct nl_msg {
    struct nlmsghdr n;
    struct genlmsghdr g;
    char buf[1024];
};

int get_family_id(int sock, const char *family_name) {
    struct nl_msg msg;
    struct nlattr *na;
    int len;

    memset(&msg, 0, sizeof(msg));
    msg.n.nlmsg_len = NLMSG_LENGTH(GENL_HDRLEN);
    msg.n.nlmsg_type = GENL_ID_CTRL;
    msg.n.nlmsg_flags = NLM_F_REQUEST;
    msg.n.nlmsg_seq = 1;
    msg.n.nlmsg_pid = getpid();
    msg.g.cmd = CTRL_CMD_GETFAMILY;
    msg.g.version = 1;

    na = (struct nlattr *) GENLMSG_DATA(&msg);
    na->nla_type = CTRL_ATTR_FAMILY_NAME;
    na->nla_len = strlen(family_name) + 1 + NLA_HDRLEN;
    strcpy((char *) NLA_DATA(na), family_name);

    msg.n.nlmsg_len += NLMSG_ALIGN(na->nla_len);

    if (send(sock, &msg, msg.n.nlmsg_len, 0) < 0) {
        perror("send");
        return -1;
    }

    len = recv(sock, &msg, sizeof(msg), 0);
    if (len < 0) {
        perror("recv");
        return -1;
    }

    if (msg.n.nlmsg_type == NLMSG_ERROR) {
        printf("Received NLMSG_ERROR\n");
        return -1;
    }

    struct nlattr *tb[CTRL_ATTR_MAX + 1];
    struct genlmsghdr *ghdr = NLMSG_DATA(&msg);
    int attrlen = len - NLMSG_LENGTH(GENL_HDRLEN);
    struct nlattr *attrs = (struct nlattr *) ((char *) ghdr + GENL_HDRLEN);

    // Parsing attributes is tedious in C without a library, but the family ID is in CTRL_ATTR_FAMILY_ID (1)
    for (; NLA_OK(attrs, attrlen); attrs = NLA_NEXT(attrs, attrlen)) {
        if (attrs->nla_type == CTRL_ATTR_FAMILY_ID) {
            return *(uint16_t *) NLA_DATA(attrs);
        }
    }

    return -1;
}

int main() {
    int sock = socket(AF_NETLINK, SOCK_RAW, NETLINK_GENERIC);
    if (sock < 0) {
        perror("socket");
        return 1;
    }

    int family_id = get_family_id(sock, NETDEV_FAMILY_NAME);
    if (family_id < 0) {
        fprintf(stderr, "Failed to get family id for %s\n", NETDEV_FAMILY_NAME);
        return 1;
    }
    printf("Family ID: %d\n", family_id);

    // We can use any interface. lo is usually UP.
    // The bug triggers when interface is DOWN.
    // We can try to find an interface or use lo and bring it down?
    // Or maybe just create a dummy interface if possible needed.
    // The reproducer used caif0 which suggests it might be available by default or created.

    // Let's try to list interfaces and find one.
    // simpler: assume lo exists. bring it down? No, that might break networking.
    // create a dummy interface.

    system("ip link add name dummy0 type dummy");
    system("ip link set dummy0 down"); // ensure it is down

    int ifindex = if_nametoindex("dummy0");
    if (ifindex == 0) {
        perror("if_nametoindex");
        // try lo if dummy0 failed? But lo is up.
        // system("ip link set lo down"); // RISKY
        return 1;
    }
    printf("Using dummy0 ifindex: %d\n", ifindex);

    struct nl_msg msg;
    memset(&msg, 0, sizeof(msg));
    msg.n.nlmsg_len = NLMSG_LENGTH(GENL_HDRLEN);
    msg.n.nlmsg_type = family_id;
    msg.n.nlmsg_flags = NLM_F_REQUEST;
    msg.n.nlmsg_seq = 2;
    msg.n.nlmsg_pid = getpid();
    msg.g.cmd = NETDEV_CMD_QUEUE_GET;
    msg.g.version = 1;

    // Attributes: ifindex, queue_id, queue_type
    struct nlattr *na;
    char *buf = (char *) GENLMSG_DATA(&msg);
    int offset = 0;

    // IFINDEX
    na = (struct nlattr *) (buf + offset);
    na->nla_type = NETDEV_A_QUEUE_IFINDEX;
    na->nla_len = NLA_HDRLEN + 4;
    *(uint32_t *) NLA_DATA(na) = ifindex;
    offset += NLMSG_ALIGN(na->nla_len);

    // QUEUE_ID = 0
    na = (struct nlattr *) (buf + offset);
    na->nla_type = NETDEV_A_QUEUE_ID;
    na->nla_len = NLA_HDRLEN + 4;
    *(uint32_t *) NLA_DATA(na) = 0;
    offset += NLMSG_ALIGN(na->nla_len);

    // QUEUE_TYPE = RX
    na = (struct nlattr *) (buf + offset);
    na->nla_type = NETDEV_A_QUEUE_TYPE;
    na->nla_len = NLA_HDRLEN + 4;
    *(uint32_t *) NLA_DATA(na) = NETDEV_QUEUE_TYPE_RX;
    offset += NLMSG_ALIGN(na->nla_len);

    msg.n.nlmsg_len += offset;

    printf("Sending NETDEV_CMD_QUEUE_GET request...\n");
    if (send(sock, &msg, msg.n.nlmsg_len, 0) < 0) {
        perror("send");
        return 1;
    }

    printf("Waiting for response... (if it crashes, we won't see this completion)\n");
    // We expect a response
    int len = recv(sock, &msg, sizeof(msg), 0);
    if (len < 0) {
        perror("recv");
        return 1;
    }
    printf("Received response of length %d\n", len);

    // Clean up
    system("ip link delete dummy0");

    return 0;
}

